import{_ as t,o,c as a,a2 as s}from"./chunks/framework.C0PoscVJ.js";const m=JSON.parse('{"title":"Role threads","description":"","frontmatter":{},"headers":[],"relativePath":"docs/agents/roles.md","filePath":"docs/agents/roles.md"}'),r={name:"docs/agents/roles.md"};function d(n,e,i,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="role-threads" tabindex="-1">Role threads <a class="header-anchor" href="#role-threads" aria-label="Permalink to &quot;Role threads&quot;">​</a></h1><p>Five long-running threads in the Claude project each own a part of the repo. Short threads (a spec, a ticket) consult them instead of guessing, and hand back what they changed. A role&#39;s memory is its files, not its thread: every decision a role makes lands in the files it owns or in a GitHub issue, so a role thread that loses its context rebuilds it by rereading them.</p><h2 id="the-roles" tabindex="-1">The roles <a class="header-anchor" href="#the-roles" aria-label="Permalink to &quot;The roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Owns</th><th>Consult it when</th></tr></thead><tbody><tr><td><strong>Architect</strong></td><td><code>CONTEXT.md</code>, <code>docs/adr/</code>, <code>docs/architecture.md</code>, SQLDelight migrations, <code>build-logic</code>, the <code>area:shared</code> and <code>area:server</code> specs</td><td>A change touches the model, the engine or the database schema; needs a word the glossary lacks; adds a module; or contradicts an ADR</td></tr><tr><td><strong>Designer</strong></td><td><code>docs/design-system.md</code>, <code>design/tokens.json</code>, the mockups, the English screen copy</td><td>A screen is added or changed, a ticket has no mockup, or Android and iOS disagree</td></tr><tr><td><strong>Poulpy keeper</strong></td><td><code>docs/brand.md</code>, <code>docs/brand-decisions.md</code>, the brand book, <code>design/build-poulpy.mjs</code>, the rules behind <code>PoulpyCoach</code> (moods, sides, tentacles), Poulpy&#39;s voice</td><td>A change affects when Poulpy reacts, what lights a tentacle or what he says; adds a reward, a notification or a pose; or touches pain and rehab</td></tr><tr><td><strong>Translator</strong></td><td>Every language other than the English source, the per-language glossaries, the translation files and their generator, the proofreading tool</td><td>A change adds or edits user-facing text, or a language is added</td></tr><tr><td><strong>Maintainer</strong></td><td><code>// CLEANUP:</code> markers, CI (<code>.github/workflows/</code>), <code>gradle/libs.versions.toml</code>, <code>.github/labels.yml</code>, the <code>device-test</code> checklists, triage</td><td>A change leaves a <code>// CLEANUP:</code> marker or a stopgap, CI is red on <code>main</code>, or a dependency needs a bump</td></tr></tbody></table><p>Roles advise; they don&#39;t overrule each other or the owner. A disagreement between roles, or anything that changes what is being built, goes to the owner as one decision.</p><h2 id="how-a-short-thread-works-with-them" tabindex="-1">How a short thread works with them <a class="header-anchor" href="#how-a-short-thread-works-with-them" aria-label="Permalink to &quot;How a short thread works with them&quot;">​</a></h2><ol><li><strong>At spec time,</strong> the spec thread asks each role whose files the idea touches, with the idea in a few lines and one precise question. The answers go into the spec and its tickets (Decided, Mockups, the ADR to write), so a ticket rarely needs a role again.</li><li><strong>At ticket time,</strong> an implementation thread asks a role only when its ticket is silent on that role&#39;s area, or when it would contradict a role&#39;s file. It sends the issue number and one question, and keeps working on the most likely answer while it waits.</li><li><strong>Decisions ship with the change.</strong> An ADR, glossary entry or brand decision goes in the same PR as the change it explains: the role writes the wording, the implementation thread commits it. A decision made at spec time with no code yet can go in a docs PR the role opens itself.</li><li><strong>Hand back.</strong> Once the PR is up, the implementation thread sends a role the PR link if it touched that role&#39;s files or departed from what was decided, and the role reviews those files. Every new <code>// CLEANUP:</code> marker goes to the Maintainer with the PR link.</li></ol><h2 id="translations" tabindex="-1">Translations <a class="header-anchor" href="#translations" aria-label="Permalink to &quot;Translations&quot;">​</a></h2><p>Every surface (Android, iOS, the website, the server&#39;s API, the exercise catalog) will read its text from one JSON file per language and per namespace, with ICU MessageFormat for plurals and placeholders. Native speakers proofread in <a href="https://fink.inlang.com/" target="_blank" rel="noreferrer">Fink</a>, which opens pull requests from a free GitHub account. A build-time generator writes the Android and iOS string files from the JSON; they are not committed. The server words only what it sends itself (emails, notifications, exports) and returns errors as codes the clients translate.</p><p>Until that move is done, the house rule stands: every string exists in English and French in Android <code>values</code> and <code>values-fr</code>, iOS <code>en.lproj</code> and <code>fr.lproj</code>, and the shared <code>Labels</code>.</p>',10)])])}const p=t(r,[["render",d]]);export{m as __pageData,p as default};
